#!/usr/bin/env python3
# =====================================================================
#  apply_dash_system.py  —  fence DASH_SYSTEM_20261117 (TD-025, TD-026, TD-027, DEF-038)
#  REQUIRES, in order: apply_page_visibility.py → apply_off_hidden.py → apply_lvb_nav.py
#                      → apply_settings_others.py
#  No engine, order or strategy code. One small read-only backend route.
#
#  1. Dashboard redesign (TD-025) on one system — components/fleet/dash.js:
#     spacing 4/8/12/16/24/32, type 11/13/15/20/32 at weights 400/600, ink /
#     muted / line + profit / loss colours only, no gradients. Book cards with
#     one hero MTM each, a quieter Fleet MTM chart (Live solid, Paper dashed,
#     overlays thin with end labels), a 9-column blotter that never scrolls
#     sideways, caption strip, broker badge as text.
#  2. Live chart redesign (TD-026): same system inside the replay window
#     (Dashboard card AND the full-screen replay on Trades / Analytics /
#     Backtest): one hero P&L, quiet legend/toolbar, thin dashed live-price
#     line, legs table on 40 px rows, notes folded behind a toggle.
#  3. Phone: the Entry/Exit meter ALONE under the focused strategy (TD-027,
#     admin, Dashboard). New GET /api/replay/meter (admin wall) = the Live
#     chart's own lookup, meter + checklist only (~1 KB, not ~100 KB of
#     candles). Every 2 s in session, 30 s otherwise, paused in background;
#     tap for the conditions. The Live chart stays desktop-only.
#  4. DEF-038: the boot overlay re-mounted the whole app as it finished — every
#     page fetched twice at start-up and the Live chart blanked once ~2 s in.
#     BackendBootGuard now keeps the app at one tree position (BOOT_NO_REMOUNT).
#
#  Files: fleet/dash.js (NEW), FleetKpis, FleetChart, FleetBlotter, TodayStrip,
#  SystemChecks, ModernDashboard, replay/TradeReplay, replay/ReplayHost,
#  StrategyHost, BackendBootGuard, backend app/api/live_replay_routes.py,
#  tests: app/api/test_replay_meter_route.py (NEW), uitest/ dash_fixture,
#  shot_dashboard, test_ui_dash_system, livechart_scene, shot_livechart,
#  test_ui_live_chart, test_ui_phone_meter (all NEW).
#
#  Run ONLY this script, outside market hours, after the other four:
#     cd ~/dev/scalp-app && python3 apply_dash_system.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
#  UI checks (optional, app closed):  cd frontend && CI=false npm run build && for t in
#     dash_system live_chart phone_meter; do PYTHONPATH=../backend python3 uitest/test_ui_$t.py; done
#  Screens:  PYTHONPATH=../backend python3 uitest/shot_dashboard.py | shot_livechart.py
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "DASH_SYSTEM_20261117"
ITEMS = json.loads(r'''[{"path": "frontend/src/components/fleet/dash.js", "orig": null, "new": "f8d2323dd4a9bcc0ed905fdbe210bd837317d690f73b4dee3fcfacd6816ae269", "blob": ""}, {"path": "frontend/src/components/fleet/FleetKpis.jsx", "orig": "34879f6ae022ca8a2203c5a405bf17328ca5282b1fc463d135fd38984adbe922", "new": "e3c017537e72d8c5890b22073961fadae7ce4ac7d09c1e644a940bc2dbf0a87d", "blob": ""}, {"path": "frontend/src/components/fleet/FleetChart.jsx", "orig": "6b9e274dd0e97d88271dc39acf7ab62b5b77ba46bbcd6cd6619577554364a0d8", "new": "0dbb8082411db8708a8e20bb53bb787dd85f2a9190f34e9d6ee99f4ee4b9facd", "blob": ""}, {"path": "frontend/src/components/fleet/FleetBlotter.jsx", "orig": "d69f3043e6435bbde926a4fe620dcec48f470e9395ac19557e96412f34f54799", "new": "33bf110c6efcc4442e1269c57fe13856798aaef123a03f58b47dc62f98112a0d", "blob": ""}, {"path": "frontend/src/components/fleet/TodayStrip.jsx", "orig": "263be05409832a559e777736303d32989d57b014f4abe50489cc8862272e855a", "new": "0ed4f17dd0681c7459cad4768d8eb4aeaa41507c7fcac5b27a256e1f14ee1832", "blob": ""}, {"path": "frontend/src/components/fleet/SystemChecks.jsx", "orig": "7bfc310782cd3c587559cd64061f72ccc9eb4a3cf42f090fe9febab49d3cfce2", "new": "a6b8ff463137ec5c7b64310e66ce141c4c01d1de8969b99fd9d3beea7dd731c6", "blob": ""}, {"path": "frontend/src/pages/ModernDashboard.jsx", "orig": "4688650a834eec5fec9d09900a56dfb7271dd833975928329c634c584b06a340", "new": "1bf00a4f5f25940d5c9f4bce343394340f5583fe09dc7cd4f92e867ceb3c15c1", "blob": ""}, {"path": "frontend/src/components/replay/TradeReplay.jsx", "orig": "1a585b2de40b3e7dda689f64d13d3c0286a4f34106e528c6a2e6fa343f58abe4", "new": "3c9a95a3fa86d7b8a9af6d7d13788e7d48e9a9b0e4d95a6c253e4041deae59d5", "blob": ""}, {"path": "frontend/src/components/replay/ReplayHost.jsx", "orig": "cc53b5f2921c5551a2b8cf37093fc87b9b5b083a4f2b5b8df7fef93a7ec69a91", "new": "4bff8c98797dcdc9f171cd85008608adf497d8967eff06769b4e3de8ae519af4", "blob": ""}, {"path": "frontend/src/components/StrategyHost.jsx", "orig": "392b6cba21694a2d750ca6baf76dc17aa51cb4b797a4fc4fd82bb49e481e6123", "new": "4ac3927d3744ec261ff190d3befc582bb1604f6d75c2379c9d4211b6b80aad2f", "blob": ""}, {"path": "frontend/src/components/BackendBootGuard.jsx", "orig": "a7112c67cb659c2cf907e773b49cee504fbeee095720eb8f245706a5a639c773", "new": "8d88a2bf45f9f1b6056353a70d273a833c70196ceb0cce1b1070b3dbdd0a7788", "blob": ""}, {"path": "backend/app/api/live_replay_routes.py", "orig": "cdcfa3600fa2ea1b0018f80195a1b50388bf17510be96d8ddecbe33462d31525", "new": "6413a2b5675b0f76bf58adae59eb7766b9729279eb26e498b8bf9286575ba6bd", "blob": ""}, {"path": "backend/app/api/test_replay_meter_route.py", "orig": null, "new": "39d117241b4ec301b62bf9e297c80c6ab85c29dab5fe32e8a83fe3ab5598ec38", "blob": ""}, {"path": "frontend/uitest/dash_fixture.py", "orig": null, "new": "07265c28f535456b7cded349dde4008afb7ce45f2c03246804a845eac8d8d732", "blob": ""}, {"path": "frontend/uitest/shot_dashboard.py", "orig": null, "new": "6620e7918d19649f9fcfa46d000a0b54c74b7fbe44d2486748decb527513e981", "blob": ""}, {"path": "frontend/uitest/test_ui_dash_system.py", "orig": null, "new": "d805fce77850b5a61fdd88b1d9806276680ce1808c5818f5cb1054d2ffdc3f79", "blob": ""}, {"path": "frontend/uitest/livechart_scene.py", "orig": null, "new": "b5a212c2ecfa5517ff4fa594f9c97ec4305d6d8a2dca9b495b433b4d19c19490", "blob": ""}, {"path": "frontend/uitest/shot_livechart.py", "orig": null, "new": "da0e8cdea0986ef40998be1e918db18dd53bd671c4789fc6c0244d7fbdc30838", "blob": ""}, {"path": "frontend/uitest/test_ui_live_chart.py", "orig": null, "new": "c4d186f087068d5d7004e46d12a9d6c68e2913fed8f5ea411ebed6f3ecddbd92", "blob": ""}, {"path": "frontend/uitest/test_ui_phone_meter.py", "orig": null, "new": "c95c13d33da00faa25c416642064ad0c91b3dc0d25b62ac8b2c9dc32ace26c7e", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/api/test_replay_meter_route.py", "app/api/test_strategy_visibility.py",
         "app/backtest/replay/test_live_replay.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: the four earlier 17-Nov scripts
if "--rollback" not in args:
    _rd = lambda r: open(os.path.join(repo, *r.split("/")), encoding="utf-8").read() if os.path.exists(os.path.join(repo, *r.split("/"))) else ""
    _app, _set = _rd("frontend/src/App.jsx"), _rd("frontend/src/pages/Settings.jsx")
    if not (all(f in _app for f in ("PAGE_VISIBILITY_20261117", "OFF_HIDDEN_20261117", "NAV_CENTER_20261117"))
            and "SETTINGS_OTHERS_20261117" in _set):
        die("run apply_page_visibility.py, apply_off_hidden.py, apply_lvb_nav.py and apply_settings_others.py "
            "first — this script builds on all four")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    later = []
    for it, p, build in targets():
        if build or not os.path.exists(p) or not os.path.exists(p + ".bak-" + FENCE):
            continue
        with open(p, "rb") as f:
            if sha(f.read()) != it["new"]:
                later.append(os.path.relpath(p, repo))
    if later:
        die("cannot roll back — changed again after this script (by a later fix or a local edit): "
            + ", ".join(later) + ". Roll the later fixes back first, newest first. Nothing was changed.")
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped, later = [], 0, [], []
_applied = False                         # this script's marker is in the tree → it was applied
for it, p, build in targets():
    if not build and os.path.exists(p):
        with open(p, "rb") as f:
            if FENCE.encode() in f.read():
                _applied = True
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    if _applied:
        later.append(rel)                # applied, then changed by a later fix
        continue
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}"
        + (f"; {len(later)} changed again by later fixes" if later else "") + ") — nothing to do")
    sys.exit(0)
if later:
    die("partly applied: " + ", ".join(later) + " changed after this script while other files are "
        "not patched — check the tree (git status) before going on. Nothing was changed.")

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        # the earlier scripts' output is expected to be uncommitted still: every planned
        # file was just proven byte-identical to it (sha == orig), so only other drift stops us.
        _ok = {os.path.relpath(p, repo) for it, p, _c, b in plan if not b and it["orig"] is not None}
        dirty = [l for l in dirty if l[3:].strip() not in _ok]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="dash_system_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        os.makedirs(os.path.dirname(p), exist_ok=True)   # a new file may need a new folder
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

# ── 5b. JSX parse gate (esbuild from frontend/node_modules, if installed) ──
_esb = os.path.join(repo, "frontend", "node_modules", ".bin", "esbuild")
if os.path.exists(_esb) and "--skip-tests" not in args:
    bad = []
    for it in ITEMS:
        if it["path"].startswith("frontend/src/") and it["path"].endswith((".jsx", ".js")):
            r = subprocess.run([_esb, os.path.join(repo, it["path"]), "--loader:.js=jsx", "--loader:.jsx=jsx",
                                "--log-level=error"], capture_output=True, text=True)
            if r.returncode != 0:
                bad.append(it["path"] + ": " + (r.stderr or "").strip()[:300])
    if bad:
        restore()
        die("JSX does not parse — every file restored:\n  " + "\n  ".join(bad))
    say("  ✓ esbuild parsed the changed frontend files")
else:
    say("  (esbuild not installed — the build will compile the frontend)")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_dash_system.py --rollback")
